#!/usr/bin/env python3
"""One-command pdf2tex pipeline for large scanned books."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import time
from pathlib import Path
from typing import Any


SCRIPT_DIR = Path(__file__).resolve().parent


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(path)


def read_json(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def page_count(pdf: Path) -> int:
    from pypdf import PdfReader

    return len(PdfReader(str(pdf)).pages)


def run_command(
    cmd: list[str | Path],
    log_path: Path | None = None,
    *,
    quiet: bool = False,
) -> subprocess.CompletedProcess[str]:
    printable = [str(item) for item in cmd]
    print(f"+ {' '.join(printable)}", flush=True)
    started = time.perf_counter()
    result = subprocess.run(
        printable,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        encoding="utf-8",
        errors="replace",
    )
    elapsed = time.perf_counter() - started
    output = result.stdout or ""
    if log_path is not None:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        log_path.write_text(
            f"command: {' '.join(printable)}\n\n{output}", encoding="utf-8"
        )
    if result.returncode != 0:
        tail = "\n".join(output.splitlines()[-40:])
        print(tail, file=sys.stderr, flush=True)
        raise RuntimeError(
            f"command failed ({result.returncode}, {elapsed:.1f}s): "
            f"{' '.join(printable)}"
        )
    if not quiet and output.strip():
        print(output.rstrip(), flush=True)
    return result


def python_script(name: str) -> Path:
    return SCRIPT_DIR / name


def plan_ranges(total_pages: int, chunk_size: int) -> list[tuple[int, int]]:
    return [
        (start, min(start + chunk_size - 1, total_pages))
        for start in range(1, total_pages + 1, chunk_size)
    ]


def chunk_id(start: int, end: int) -> str:
    return f"pages-{start:04d}-{end:04d}"


def split_ranges(start: int, end: int) -> list[tuple[int, int]]:
    middle = (start + end) // 2
    return [(start, middle), (middle + 1, end)]


def source_report(report_path: Path, failed: list[dict[str, Any]]) -> dict[str, Any]:
    if not report_path.exists():
        return {"available": False, "suspicious_pages": 0, "failed": failed}
    data = read_json(report_path)
    return {
        "available": True,
        "has_text_layer": data.get("has_text_layer"),
        "duplicate_pages": len(data.get("duplicate_pages", [])),
        "suspicious_pages": len(data.get("suspicious_pages", [])),
        "anchor_issues": data.get("anchor_issues", []),
        "failed": failed,
    }


def build_header(args: argparse.Namespace, output_path: Path) -> Path:
    if args.header:
        return args.header.resolve()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(
        "\n".join(
            [
                "% Generated by pdf2tex_run.py; override these with --header if needed.",
                "\\usepackage{fontspec}",
                "\\usepackage{unicode-math}",
                "\\usepackage{xeCJK}",
                f"\\setmainfont{{{args.main_font}}}",
                f"\\setsansfont{{{args.main_font}}}",
                f"\\setmonofont{{{args.mono_font}}}",
                f"\\setmathfont{{{args.math_font}}}",
                f"\\setCJKmainfont{{{args.cjk_font}}}",
                f"\\setCJKsansfont{{{args.cjk_font}}}",
                f"\\setCJKmonofont{{{args.cjk_font}}}",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    return output_path


class Pipeline:
    def __init__(self, args: argparse.Namespace) -> None:
        self.args = args
        self.pdf = args.pdf.resolve()
        self.out = args.output.resolve()
        self.chunks_dir = self.out / "chunks"
        self.book_dir = self.out / "book"
        self.logs_dir = self.out / "logs"
        self.source_hash = sha256(self.pdf)
        self.pages = page_count(self.pdf)
        self.name = args.name or re.sub(r'[\\/:*?"<>|]+', "_", self.pdf.stem)
        self.chunks: list[dict[str, Any]] = []
        self.failed_chunks: list[dict[str, Any]] = []

    def run_remote_step(self, cmd: list[str | Path], log_name: str) -> None:
        run_command(cmd, self.logs_dir / log_name, quiet=True)

    def audit(self) -> None:
        if self.args.no_audit:
            return
        report = self.out / "scan-audit.json"
        run_command(
            [
                sys.executable,
                python_script("audit_scan_pages.py"),
                self.pdf,
                "--out",
                report,
                "--quiet",
            ],
            self.logs_dir / "audit.log",
            quiet=True,
        )

    def update_chunk_state(self, state_path: Path, record: dict[str, Any]) -> None:
        state = read_json(state_path)
        state.update(
            {
                "source_pdf": str(self.pdf),
                "source_sha256": self.source_hash,
                "source_page_count": self.pages,
                "source_pages": [record["start"], record["end"]],
                "language": self.args.language,
                "engine": "remote-mineru-v4",
            }
        )
        write_json(state_path, state)

    def process_chunk(self, start: int, end: int, depth: int = 0) -> list[dict[str, Any]]:
        label = chunk_id(start, end)
        subset_pdf = self.chunks_dir / f"{label}.pdf"
        manifest = self.chunks_dir / f"{label}.manifest.json"
        chunk_dir = self.chunks_dir / label
        record: dict[str, Any] = {
            "id": label,
            "start": start,
            "end": end,
            "page_count": end - start + 1,
            "subset_pdf": str(subset_pdf),
            "manifest": str(manifest),
            "ocr_dir": str(chunk_dir / "attempt-01"),
            "status": "pending",
        }

        candidates = sorted(chunk_dir.glob("attempt-*"), reverse=True)
        for candidate in candidates:
            candidate_md = candidate / "result" / "full.md"
            candidate_state = read_json(candidate / "state.json")
            if (
                candidate_md.is_file()
                and candidate_md.stat().st_size > 0
                and candidate_state.get("status") == "done"
                and candidate_state.get("source_sha256") == self.source_hash
                and candidate_state.get("language") == self.args.language
            ):
                record["ocr_dir"] = str(candidate)
                record["status"] = "reused"
                self.chunks.append(record)
                print(f"chunk {label}: reused existing OCR result", flush=True)
                return [record]

        if not subset_pdf.exists():
            run_command(
                [
                    sys.executable,
                    python_script("extract_pdf_pages.py"),
                    self.pdf,
                    subset_pdf,
                    "--pages",
                    f"{start}-{end}",
                    "--manifest",
                    manifest,
                ],
                self.logs_dir / f"{label}-extract.log",
                quiet=True,
            )

        attempts = 0
        last_error: str | None = None
        max_attempts = max(1, self.args.retries + 1)
        while attempts < max_attempts:
            attempts += 1
            ocr_dir = chunk_dir / f"attempt-{attempts:02d}"
            state_path = ocr_dir / "state.json"
            result_md = ocr_dir / "result" / "full.md"
            try:
                self.run_remote_step(
                    [
                        sys.executable,
                        python_script("mineru_pipeline.py"),
                        "v4",
                        subset_pdf,
                        ocr_dir,
                        "--language",
                        self.args.language,
                    ],
                    f"{label}-attempt-{attempts}.log",
                )
                if not result_md.is_file() or result_md.stat().st_size == 0:
                    raise RuntimeError("MinerU finished but result/full.md is missing")
                record["status"] = "done"
                record["ocr_dir"] = str(ocr_dir)
                record["attempts"] = attempts
                self.update_chunk_state(state_path, record)
                self.chunks.append(record)
                print(f"chunk {label}: done", flush=True)
                return [record]
            except Exception as exc:
                last_error = str(exc)
                print(f"chunk {label}: attempt {attempts} failed: {exc}", flush=True)

        if end - start + 1 > self.args.min_chunk_pages and depth < self.args.max_depth:
            print(f"chunk {label}: splitting after failure", flush=True)
            children: list[dict[str, Any]] = []
            for child_start, child_end in split_ranges(start, end):
                children.extend(
                    self.process_chunk(child_start, child_end, depth + 1)
                )
            if all(item["status"] in {"done", "reused"} for item in children):
                return children

        record["status"] = "failed"
        record["attempts"] = attempts
        record["error"] = last_error
        self.failed_chunks.append(record)
        self.chunks.append(record)
        return [record]

    def process_all(self) -> None:
        for start, end in plan_ranges(self.pages, self.args.chunk_size):
            self.process_chunk(start, end)
        if self.failed_chunks:
            failed = ", ".join(
                f"{item['start']}-{item['end']}" for item in self.failed_chunks
            )
            raise RuntimeError(f"OCR failed for source pages: {failed}")

    def write_page_map(self) -> Path:
        page_map = {
            "source_pdf": str(self.pdf),
            "source_sha256": self.source_hash,
            "source_page_count": self.pages,
            "chunk_size": self.args.chunk_size,
            "chunks": sorted(self.chunks, key=lambda item: item["start"]),
        }
        path = self.out / "page-map.json"
        write_json(path, page_map)
        return path

    def merge_markdown(self) -> Path:
        self.book_dir.mkdir(parents=True, exist_ok=True)
        successful = sorted(
            [item for item in self.chunks if item["status"] in {"done", "reused"}],
            key=lambda item: item["start"],
        )
        config = {
            "out": str(self.book_dir),
            "blocks": [
                {
                    "label": item["id"],
                    "md": str(Path(item["ocr_dir"]) / "result" / "full.md"),
                    "images": str(Path(item["ocr_dir"]) / "result" / "images"),
                }
                for item in successful
            ],
            "volumes": [
                {
                    "name": self.name,
                    "file": "book.md",
                    "segments": [[item["id"], 1, None] for item in successful],
                }
            ],
        }
        config_path = self.out / "merge-volumes.json"
        write_json(config_path, config)
        run_command(
            [sys.executable, python_script("merge_volumes.py"), config_path],
            self.logs_dir / "merge-volumes.log",
        )
        return self.book_dir / "book.md"

    def validate_markdown(self, markdown: Path) -> dict[str, Any]:
        report_path = self.book_dir / "markdown-validation.json"
        run_command(
            [
                sys.executable,
                python_script("validate_markdown.py"),
                markdown,
                "--report",
                report_path,
            ],
            self.logs_dir / "validate-markdown.log",
            quiet=True,
        )
        report = read_json(report_path)
        if report.get("replacement_chars", 0):
            raise RuntimeError("Markdown contains replacement characters")
        if report.get("unbalanced_math_blocks", 0):
            raise RuntimeError("Markdown has unbalanced $$ math blocks")
        return report

    def build_outputs(self) -> dict[str, Any]:
        markdown = self.merge_markdown()
        fixed_md = self.book_dir / "book.fixed.md"
        compat_md = self.book_dir / "book.compat.md"
        run_command(
            [
                sys.executable,
                python_script("repair_latex.py"),
                markdown,
                fixed_md,
                "--report",
                self.book_dir / "repair-report.json",
            ],
            self.logs_dir / "repair-latex.log",
            quiet=True,
        )
        run_command(
            [
                sys.executable,
                python_script("fix_html_tables.py"),
                fixed_md,
                "--patch-md",
                compat_md,
            ],
            self.logs_dir / "fix-html-tables.log",
            quiet=True,
        )
        markdown_report = self.validate_markdown(compat_md)
        final_md = self.book_dir / f"{self.name}.md"
        shutil.copy2(compat_md, final_md)

        outputs: dict[str, Any] = {
            "merged_markdown": str(markdown),
            "final_markdown": str(final_md),
            "markdown_validation": markdown_report,
        }
        if self.args.no_pdf:
            return outputs

        if not shutil.which("pandoc"):
            raise RuntimeError("pandoc is required for TeX/PDF output")
        if not shutil.which("xelatex"):
            raise RuntimeError("xelatex is required for TeX/PDF output")

        header = build_header(self.args, self.book_dir / "pandoc-header.tex")
        tex = self.book_dir / f"{self.name}.tex"
        run_command(
            [
                "pandoc",
                compat_md,
                "--standalone",
                "--pdf-engine=xelatex",
                "--resource-path",
                str(self.book_dir),
                "-H",
                header,
                "-o",
                tex,
            ],
            self.logs_dir / "pandoc-tex.log",
            quiet=True,
        )
        validation_dir = self.book_dir / "validation"
        run_command(
            [sys.executable, python_script("validate_latex.py"), tex, validation_dir],
            self.logs_dir / "validate-latex.log",
            quiet=True,
        )
        compile_report = read_json(validation_dir / "compile-report.json")
        outputs["latex"] = str(tex)
        outputs["validation"] = compile_report
        if compile_report.get("passed") is True:
            if compile_report.get("missing_glyph_count", 0) != 0:
                raise RuntimeError("XeLaTeX compiled but reported missing glyphs")
            compiled_pdf = validation_dir / f"{tex.stem}.pdf"
            final_pdf = self.book_dir / f"{self.name}.pdf"
            shutil.copy2(compiled_pdf, final_pdf)
            outputs["pdf"] = str(final_pdf)
        else:
            raise RuntimeError("XeLaTeX validation failed; see validation/compile-report.json")
        return outputs

    def run(self) -> dict[str, Any]:
        self.out.mkdir(parents=True, exist_ok=True)
        self.chunks_dir.mkdir(parents=True, exist_ok=True)
        self.logs_dir.mkdir(parents=True, exist_ok=True)
        if not self.args.plan_only and not os.environ.get("MINERU_API_TOKEN", "").strip():
            raise RuntimeError("MINERU_API_TOKEN is required; tokens must come from the environment")

        if self.args.plan_only:
            plan = {
                "source_pdf": str(self.pdf),
                "source_sha256": self.source_hash,
                "source_page_count": self.pages,
                "chunk_size": self.args.chunk_size,
                "chunks": plan_ranges(self.pages, self.args.chunk_size),
            }
            write_json(self.out / "plan.json", plan)
            print(json.dumps(plan, ensure_ascii=False, indent=2))
            return plan

        self.audit()
        self.process_all()
        page_map = self.write_page_map()
        outputs = self.build_outputs()
        repair_report = read_json(self.book_dir / "repair-report.json")
        summary = {
            "source": {
                "file": str(self.pdf),
                "sha256": self.source_hash,
                "pages": self.pages,
            },
            "settings": {
                "engine": "remote-mineru-v4",
                "language": self.args.language,
                "chunk_size": self.args.chunk_size,
                "min_chunk_pages": self.args.min_chunk_pages,
                "max_depth": self.args.max_depth,
            },
            "chunks": sorted(self.chunks, key=lambda item: item["start"]),
            "scan_audit": source_report(self.out / "scan-audit.json", self.failed_chunks),
            "outputs": outputs,
            "quality": {
                "tag_fixes": repair_report.get("tag_fixes"),
                "array_fixes": repair_report.get("array_fixes"),
                "markdown_validation": outputs.get("markdown_validation"),
                "latex_validation": outputs.get("validation"),
            },
            "page_map": str(page_map),
            "notes": [
                "Local MinerU is not required; V4 uses the MinerU API.",
                "MINERU_API_TOKEN is read only from the environment and is never written to reports.",
            ],
        }
        write_json(self.out / "run-summary.json", summary)
        print(json.dumps(summary, ensure_ascii=False, indent=2))
        return summary


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("pdf", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--language", default="ch")
    parser.add_argument("--name", help="basename for final Markdown/TeX/PDF")
    parser.add_argument("--chunk-size", type=int, default=50)
    parser.add_argument("--min-chunk-pages", type=int, default=10)
    parser.add_argument("--max-depth", type=int, default=4)
    parser.add_argument("--retries", type=int, default=1)
    parser.add_argument("--header", type=Path, help="custom pandoc header")
    parser.add_argument("--cjk-font", default="SimSun")
    parser.add_argument("--main-font", default="DejaVu Sans")
    parser.add_argument("--mono-font", default="DejaVu Sans Mono")
    parser.add_argument("--math-font", default="Cambria Math")
    parser.add_argument("--no-audit", action="store_true")
    parser.add_argument("--no-pdf", action="store_true")
    parser.add_argument("--plan-only", action="store_true")
    args = parser.parse_args()
    if args.chunk_size < 1 or args.min_chunk_pages < 1:
        parser.error("chunk sizes must be positive")
    if args.chunk_size > 200:
        parser.error("MinerU V4 accepts at most 200 pages per input")
    try:
        Pipeline(args).run()
    except Exception as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
